/*
 * A371896  a(n) is the length of the uninterrupted sequence of primes
 *          generated by the polynomial f(x) = x^2 + x + p for x=0,1,...,
 *          where p=A001359(n).
 * https://oeis.org/A371896
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = length of the longest prefix of primes produced by f(x) =
 *            x^2 + x + p, where p = the n‑th smaller twin prime
 * Range:     u8 n <= 17, u16 n <= 1414, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 7837, big any n
 * Helpers:   is_prime
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/is_prime.h"   /* provides bool is_prime(idx_t) */

/* state for twin‑prime generation ------------------------------------- */
static seq_t *twin_primes = NULL;         /* array of twin‑prime starts */
static size_t twin_cap   = 0;             /* allocated capacity       */
static idx_t  twin_cnt   = 0;             /* number stored            */
static idx_t  last_checked = 3;           /* next odd number to test */

/* expand twin_primes array if needed */
static void
ensure_twin_primes(idx_t n)
{
    if (twin_cnt >= n)
        return;

    /* grow array */
    if (twin_cnt == twin_cap) {
        size_t new_cap = twin_cap ? twin_cap * 2 : 4;
        seq_t *new_arr = (seq_t *)realloc(twin_primes, new_cap * sizeof(seq_t));
        if (!new_arr) exit(EXIT_FAILURE);
        twin_primes = new_arr;
        twin_cap = new_cap;
    }

    /* search for further twin primes */
    while (twin_cnt < n) {
        if (last_checked % 2 == 0)
            ++last_checked;                     /* keep odd */

        if (is_prime(last_checked) && is_prime(last_checked + 2))
            twin_primes[twin_cnt++] = (seq_t)last_checked;

        last_checked += 2;                     /* next odd candidate */
    }
}

/* --------------------------------------------------------------------- */
seq_t
a(idx_t n)
{
    if (n == 0)          /* offset is 1; behavior below is irrelevant */
        return 0;

    /* obtain the required twin prime */
    ensure_twin_primes(n);
    seq_t p = twin_primes[n - 1];

    /* count successive primes from f(x) = x^2 + x + p */
    seq_t  count = 0;
    seq_t  x     = 0;

    for (;;) {
        idx_t val = (idx_t)x * (idx_t)x + (idx_t)x + (idx_t)p;
        if (!is_prime(val))
            break;
        ++count;
        ++x;
    }
    return count;
}
